package com.pantrybase.api.cooking.dto;

import jakarta.validation.constraints.NotNull;

/**
 * What the caller needs to open a cooking session.
 *
 * <p>A single long: the recipe id. Opening a session records no quantity of its own —
 * the amounts live in the recipe — so there is nothing else for the caller to state,
 * and the response is generated by the server rather than echoed from the request.</p>
 */
public record CreateCookingSessionRequest(
        @NotNull Long recipeId
) {}